// Parse real TTF fonts with embedded bitmap strikes.
//
// These are the CC0 reproducers from thorvg issue #4945, built from scratch
// with fontTools (see the README alongside them) for exactly this purpose: one
// 16 ppem 1-bit strike containing .notdef, space, 'A' and 'B'. At 1.3 KB each
// they are the smallest useful embedded-bitmap fonts available, and because
// they were generated by an independent tool they are a genuine test of the
// reader rather than of my own understanding.

import { describe, it, expect } from 'vitest'
import { readFileSync } from 'node:fs'
import { resolve } from 'node:path'
import { parseSbit, isSbitFont } from './sbitParser'

const DIR = resolve(__dirname, '../testFixtures/ttf')

function load(name: string): ArrayBuffer {
  const b = readFileSync(resolve(DIR, name))
  return b.buffer.slice(b.byteOffset, b.byteOffset + b.byteLength) as ArrayBuffer
}

/** Table tags present in an sfnt. */
function tableTags(buf: ArrayBuffer): string[] {
  const view = new DataView(buf)
  const bytes = new Uint8Array(buf)
  const count = view.getUint16(4)
  const tags: string[] = []
  for (let i = 0; i < count; i++) {
    const p = 12 + i * 16
    tags.push(String.fromCharCode(bytes[p], bytes[p + 1], bytes[p + 2], bytes[p + 3]))
  }
  return tags
}

describe('real embedded-bitmap fonts: OpenType layout', () => {
  const name = 'bitmap-opentype.ttf'

  it('is recognised as an sbit font', () => {
    expect(isSbitFont(load(name))).toBe(true)
  })

  it('carries the EBLC/EBDT tables this parser reads', () => {
    const tags = tableTags(load(name))
    expect(tags).toContain('EBLC')
    expect(tags).toContain('EBDT')
    // No outlines at all, so the bitmaps are the only glyph source
    expect(tags).not.toContain('glyf')
  })

  it('reports the one strike the file contains', () => {
    const result = parseSbit(load(name))
    expect(result.strikes.length).toBe(1)
    expect(result.strikes[0].ppemX).toBe(16)
    expect(result.strikes[0].ppemY).toBe(16)
  })

  it('lays the glyphs out at 16x16 starting from the space character', () => {
    const strike = parseSbit(load(name)).strikes[0]
    expect(strike.glyphWidth).toBe(16)
    expect(strike.glyphHeight).toBe(16)
    expect(strike.startChar).toBe(32)
  })

  it('marks exactly the three glyphs the font defines as populated', () => {
    // space, 'A', 'B' => offsets 0, 33, 34 from startChar 32
    const strike = parseSbit(load(name)).strikes[0]
    expect(strike.populated.size).toBe(3)
    expect([...strike.populated].sort((a, b) => a - b)).toEqual([0, 33, 34])
  })

  it('sizes the glyph buffer for the span it covers', () => {
    const strike = parseSbit(load(name)).strikes[0]
    const bpr = Math.ceil(strike.glyphWidth / 8)
    expect(strike.fontData.length).toBe((strike.populated.size > 0 ? 35 : 0) * strike.glyphHeight * bpr)
  })

  it('reads glyph data that contains ink, not blank cells', () => {
    const strike = parseSbit(load(name)).strikes[0]
    const inked = [...strike.fontData].filter(b => b !== 0).length
    // 'A' and 'B' are drawn, space and .notdef are not
    expect(inked).toBeGreaterThan(0)
  })

  it('separates the two inked glyphs', () => {
    const strike = parseSbit(load(name)).strikes[0]
    const bpr = Math.ceil(strike.glyphWidth / 8)
    const bpg = strike.glyphHeight * bpr
    const glyphA = strike.fontData.subarray(33 * bpg, 34 * bpg)
    const glyphB = strike.fontData.subarray(34 * bpg, 35 * bpg)
    expect([...glyphA].some(b => b !== 0)).toBe(true)
    expect([...glyphB].some(b => b !== 0)).toBe(true)
    // Different letters must not produce identical bitmaps
    expect([...glyphA]).not.toEqual([...glyphB])
  })
})

describe('real embedded-bitmap fonts: Apple layout', () => {
  const name = 'bitmap-apple.ttf'

  it('uses Apple\'s older sfnt version and bloc/bdat tables', () => {
    const buf = load(name)
    expect(new DataView(buf).getUint32(0)).toBe(0x74727565) // 'true'
    const tags = tableTags(buf)
    expect(tags).toContain('bloc')
    expect(tags).toContain('bdat')
    expect(tags).toContain('bhed')
    expect(tags).not.toContain('head')
    expect(tags).not.toContain('glyf')
  })

  it('is recognised as an sbit font', () => {
    // This used to return false: the table walk handled bloc/bdat but the entry
    // point rejected the 'true' sfnt version, so the Apple path was unreachable
    expect(isSbitFont(load(name))).toBe(true)
  })

  it('parses to the same strike as the OpenType version', () => {
    // Both files hold identical bitmaps, differing only in table naming
    const apple = parseSbit(load(name)).strikes[0]
    const opentype = parseSbit(load('bitmap-opentype.ttf')).strikes[0]
    expect(apple.ppemX).toBe(opentype.ppemX)
    expect(apple.ppemY).toBe(opentype.ppemY)
    expect(apple.startChar).toBe(opentype.startChar)
    expect([...apple.populated].sort((a, b) => a - b))
      .toEqual([...opentype.populated].sort((a, b) => a - b))
    expect([...apple.fontData]).toEqual([...opentype.fontData])
  })
})

describe('real embedded-bitmap fonts: rejection of non-sbit input', () => {
  it('rejects a buffer too short to be an sfnt', () => {
    expect(isSbitFont(new ArrayBuffer(8))).toBe(false)
  })

  it('rejects a plain TTF version tag with no bitmap tables', () => {
    // A minimal sfnt header claiming .notdef only, with no EBLC/bloc
    const buf = new ArrayBuffer(28)
    const view = new DataView(buf)
    view.setUint32(0, 0x00010000)
    view.setUint16(4, 1)
    expect(isSbitFont(buf)).toBe(false)
  })

  it('throws from parseSbit rather than returning a partial result', () => {
    const buf = new ArrayBuffer(28)
    new DataView(buf).setUint32(0, 0x00010000)
    expect(() => parseSbit(buf)).toThrow()
  })
})
